before:
Complete local Go example; the app itself does not execute it:
```go
package study
import ("testing"; "net/http"; "net/http/httptest"; "fmt")
func handler(w http.ResponseWriter, r *http.Request) {
    if r.URL.Path != "/study" { http.NotFound(w, r); return }
    if _, err := fmt.Fprint(w, "ready"); err != nil { return }
}
func TestHandler(t *testing.T) {
    request := httptest.NewRequest(http.MethodGet, "/study", nil)
    recorder := httptest.NewRecorder()
    handler(recorder, request)
    if recorder.Code != http.StatusOK { t.Fatalf("unexpected status: %d", recorder.Code) }
    if recorder.Body.String() != "ready" { t.Fatalf("unexpected body: %q", recorder.Body.String()) }
}
```

